function check(input, actual, expected) {
  const s = input[0];
  const isDigit = c => c >= '0' && c <= '9';
  let digits = 0;
  for (const c of s) if (isDigit(c)) digits++;
  const letters = s.length - digits;
  if (Math.abs(letters - digits) > 1) return actual === '';
  if (typeof actual !== 'string' || actual.length !== s.length) return false;
  if ([...actual].sort().join('') !== [...s].sort().join('')) return false;
  for (let i = 1; i < actual.length; i++) if (isDigit(actual[i]) === isDigit(actual[i - 1])) return false;
  return true;
}

