function validate([s]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 500) return 's needs 1 to 500 characters.';
  if (!/^[a-z0-9]+$/.test(s)) return 's may only contain lowercase letters and digits.';
  return null;
}

