function reformat(s) {
  const letters = [];
  const digits = [];
  for (const ch of s) {
    if (ch >= '0' && ch <= '9') {
      digits.push(ch);
    } else {
      letters.push(ch);
    }
  }
  if (Math.abs(letters.length - digits.length) > 1) {
    return '';
  }
  const first = digits.length >= letters.length ? digits : letters;
  const second = first === digits ? letters : digits;
  const result = [];
  for (let i = 0; i < first.length; i++) {
    result.push(first[i]);
    if (i < second.length) {
      result.push(second[i]);
    }
  }
  return result.join('');
}

