function reformat(s) {
  const pools = new Map([['digit', []], ['letter', []]]);
  for (const c of s) pools.get(/[0-9]/.test(c) ? 'digit' : 'letter').push(c);
  // Start with the larger group, then always take the other group; give up when it runs dry.
  let turn = pools.get('letter').length > pools.get('digit').length ? 'letter' : 'digit';
  let out = '';
  while (out.length < s.length) {
    if (!pools.get(turn).length) return '';
    out += pools.get(turn).pop();
    turn = turn === 'letter' ? 'digit' : 'letter';
  }
  return out;
}

