function generate(rand, size) {
  const n = size === 'large' ? 400 + Math.floor(rand() * 101) : 1 + Math.floor(rand() * 10);
  let letterCount;
  const mode = rand();
  if (mode < 0.6) letterCount = Math.floor(n / 2) + (n % 2 && rand() < 0.5 ? 1 : 0);
  else if (mode < 0.8) letterCount = Math.floor(rand() * (n + 1));
  else letterCount = rand() < 0.5 ? 0 : n;
  const alphabet = rand() < 0.3 ? 'ab' : 'abcdefghijklmnopqrstuvwxyz';
  const chars = [];
  for (let i = 0; i < letterCount; i++) chars.push(alphabet[Math.floor(rand() * alphabet.length)]);
  for (let i = letterCount; i < n; i++) chars.push(String(Math.floor(rand() * 10)));
  for (let i = chars.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [chars[i], chars[j]] = [chars[j], chars[i]];
  }
  return [chars.join('')];
}
